#include <iostream>
#include <vector>
using namespace std;


struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};


class Solution {
public:
    void flatten(TreeNode* root){
        if (!root)
            return;
        if (!root->left)
            flatten(root->right);
        else if (!root->right){
            root->right = root->left;
            root->left = NULL;
            flatten(root->right);
        }
        else {
            TreeNode* l = root->left, *r = root->right;
            flatten(l);
            flatten(r);
            root->right = l;
            root->left = NULL;
            while (l->right)
                l = l->right;
            l->right = r;
        }
    }
};

