/*
 * @lc app=leetcode.cn id=121 lang=php
 *
 * [121] 买卖股票的最佳时机
 *
 * https://leetcode-cn.com/problems/best-time-to-buy-and-sell-stock/description/
 *
 * algorithms
 * Easy (50.73%)
 * Likes:    588
 * Dislikes: 0
 * Total Accepted:    88.3K
 * Total Submissions: 172.7K
 * Testcase Example:  '[7,1,5,3,6,4]'
 *
 * 给定一个数组，它的第 i 个元素是一支给定股票第 i 天的价格。
 * 
 * 如果你最多只允许完成一笔交易（即买入和卖出一支股票），设计一个算法来计算你所能获取的最大利润。
 * 
 * 注意你不能在买入股票前卖出股票。
 * 
 * 示例 1:
 * 
 * 输入: [7,1,5,3,6,4]
 * 输出: 5
 * 解释: 在第 2 天（股票价格 = 1）的时候买入，在第 5 天（股票价格 = 6）的时候卖出，最大利润 = 6-1 = 5 。
 * ⁠    注意利润不能是 7-1 = 6, 因为卖出价格需要大于买入价格。
 * 
 * 
 * 示例 2:
 * 
 * 输入: [7,6,4,3,1]
 * 输出: 0
 * 解释: 在这种情况下, 没有交易完成, 所以最大利润为 0。
 * 
 * 
 */
// @lc code=start
class Solution {

    /**
     * @param Integer[] $prices
     * @return Integer
     */
    function maxProfit($prices) {
        // dp思路：第i天最大收益=max{第i-1天最大收益, 第i天价格-i天之前最小价格}    
        $profits = [0];
        $minPrice = $prices[0];
        $maxProfit = 0;

        foreach ($prices as $index => $price) {
            if ($index == 0) {
                continue;
            }

            if ($profits[$index - 1] > $price - $minPrice) {
                $profits[] = $profits[$index - 1];
            } else {
                $profits[] = $price - $minPrice;
            }
            $maxProfit = $profits[$index] > $maxProfit ? $profits[$index] : $maxProfit;
            // 重新计算最小价格
            $minPrice = $minPrice > $price ? $price : $minPrice;
        }

        return $maxProfit;
    }
}
// @lc code=end

package main

import (
	"reflect"
	"testing"
)

func Test_parseInput(t *testing.T) {
	type args struct {
		input string
	}
	tests := []struct {
		name string
		args args
		want []string
	}{
		{
			name: "singleURL",
			args: args{input: "http://hello.world"},
			want: []string{"http://hello.world"},
		},
		{
			name: "listURLS",
			args: args{input: "[\"http://hello.world\",\"http://example.com\",\"http://golang.org\"]"},
			want: []string{"http://hello.world", "http://example.com", "http://golang.org"},
		},
		{
			name: "malformedLeft",
			args: args{input: "\"http://hello.world\",\"http://example.com\",\"http://golang.org\"]"},
			want: []string{"\"http://hello.world\",\"http://example.com\",\"http://golang.org\"]"},
		},
		{
			name: "malformedRight",
			args: args{input: "[\"http://hello.world\",\"http://example.com\",\"http://golang.org\""},
			want: []string{"[\"http://hello.world\",\"http://example.com\",\"http://golang.org\""},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := parseInput(tt.args.input); !reflect.DeepEqual(got, tt.want) {
				t.Errorf("parseInput() = %v, want %v", got, tt.want)
			}
		})
	}
}

func Test_validateURLs(t *testing.T) {
	type args struct {
		records []string
	}
	tests := []struct {
		name    string
		args    args
		wantErr bool
	}{
		{
			name:    "all valid",
			args:    args{[]string{"http://ya.ru", "http://example.com", "http://v.moc"}},
			wantErr: false,
		},
		{
			name:    "all invalid",
			args:    args{[]string{"://ya.ru", "http:example.com", "v.moc"}},
			wantErr: true,
		},
		{
			name:    "some valid",
			args:    args{[]string{"http://ya.ru", "example.com", ""}},
			wantErr: true,
		},
		{
			name:    "one valid",
			args:    args{[]string{"http://example.com"}},
			wantErr: false,
		},
		{
			name:    "one invalid",
			args:    args{[]string{".com"}},
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := validateURLs(tt.args.records); (err != nil) != tt.wantErr {
				t.Errorf("validateURLs() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

// Median of Two Sorted Arrays
// There are two sorted arrays A and B of size m and n respectively. Find the median of the two sorted arrays. The overall run time complexity should be O(log (m+n)).

// Consider there are N numbers in sorted array A,
// If N is odd, the median is (A[N/2]+A[N/2+1])/2;
// If N is even, the median is A[N/2].
//
// Just a exercise to study how to use heap, not the optimal method.

#define LEFT(i) (2*(i)+1)
#define RIGHT(i) (2*(i)+2)
#define PARENT(i) (((i)-1)/2)

void minHeapify(int A[], int i, int size)
{
    if (size <= 0) return;

    int smallest = i;
    if (LEFT(i) < size && A[LEFT(i)] < A[smallest])
        smallest = LEFT(i);
    if (RIGHT(i) < size && A[RIGHT(i)] < A[smallest])
        smallest = RIGHT(i);

    if (smallest != i)
    {
        std::swap(A[smallest], A[i]);
        minHeapify(A, smallest, size);
    }
}

int extractMin(int A[], int size)
{
    if (size <= 0) return -1;

    int min = A[0];
    std::swap(A[0], A[size-1]);

    minHeapify(A, 0, size-1);

    return min;
}

double findMedianSortedArrays(int A[], int m, int B[], int n)
{
    int mid = (m+n)/2;
    if ((m+n)%2 == 1)
        mid = (m+n+1)/2;
    double median = 0.0;

    if (m == 0 && n == 0)
    {
        return 0.0;
    }
    else if (m == 0 && n != 0)
    {
        if (n%2 == 0)
            median = ((double)B[n/2-1]+(double)B[n/2+1-1])/2;
        else
            median = B[(n+1)/2-1];
        return median;
    }
    else if (m != 0 && n == 0)
    {
        if (m%2 == 0)
            median = ((double)A[m/2-1]+(double)A[m/2+1-1])/2;
        else
            median = A[(m+1)/2-1];
        return median;
    }

    int i = m;
    int j = n;
    while (mid > 0 && i > 0 && j > 0)
    {
        if (A[0] < B[0])
        {
            median = extractMin(A, i);
            --i;
        }
        else
        {
            median = extractMin(B, j);
            --j;
        }
        --mid;
    }

    while (mid > 0)
    {
        if (i == 0)
        {
            median = extractMin(B, j);
            --j;
        }
        else
        {
            median = extractMin(A, i);
            --i;
        }
        mid--;
    }

    if ((m+n)%2 == 0)
    {
        if (i != 0 && j != 0)
        {
            median += min(A[0], B[0]);
        }
        else if (i == 0)
        {
            median += B[0];
        }
        else
        {
            median += A[0];
        }
        median = median/2;
    }

    return median;
}
